// Build a valid triangle mesh (V,F) and call igl::avg_edge_length ensuring constraints.
// Constraints enforced:
//  - V: #V-by-3 (dim >= 2; we choose 3D) with finite coordinates.
//  - F: #F-by-3 (triangles), indices in [0, #V-1], with distinct vertices per face.
//  - #V >= 3, #F >= 1.
//  - Result must be finite and >= 0.

// Choose mesh sizes within small bounds for performance
unsigned int rV = *FUZZ_PARAM(unsigned int);
unsigned int rF = *FUZZ_PARAM(unsigned int);
int nV = (int)(rV % 64u) + 3;   // [3, 66]
int nF = (int)(rF % 128u) + 1;  // [1, 128]

// Seed a simple PRNG from fuzz input for reproducible, varied coordinates
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
auto next_u64 = [&seed]() -> unsigned long long {
  // xorshift64*
  seed ^= seed >> 12; seed ^= seed << 25; seed ^= seed >> 27; return seed * 2685821657736338717ULL;
};
auto next_double = [&]() -> double {
  // Map to [-10, 10]
  const double inv = 1.0 / (double)std::numeric_limits<unsigned long long>::max();
  double u = (double)(next_u64()) * inv; // [0,1]
  return -10.0 + 20.0 * u;
};

// Construct V (#V x 3)
Eigen::MatrixXd V(nV, 3);
for (int i = 0; i < nV; ++i) {
  V(i,0) = next_double();
  V(i,1) = next_double();
  V(i,2) = next_double();
}

// Construct F (#F x 3) with distinct vertex indices per face
Eigen::MatrixXi F(nF, 3);
for (int i = 0; i < nF; ++i) {
  if (nV < 3) { FUZZ_BAIL(); }
  int a = (int)(next_u64() % (unsigned long long)nV);
  int b = (int)(next_u64() % (unsigned long long)(nV - 1)); if (b >= a) { b += 1; }
  int c = (int)(next_u64() % (unsigned long long)(nV - 2));
  // Map c to an index distinct from a and b
  if (c >= std::min(a,b)) { c += 1; }
  if (c >= std::max(a,b)) { c += 1; }
  // Now a, b, c are distinct and within [0, nV-1]
  F(i,0) = a; F(i,1) = b; F(i,2) = c;
}

// Invoke target function
double avg = igl::avg_edge_length(V, F);

// Property-based validations: average edge length should be finite and non-negative.
FUZZ_ASSERT(std::isfinite(avg), "avg_edge_length must be finite");
FUZZ_ASSERT(avg >= 0.0, "avg_edge_length must be non-negative");

// No persistent outputs to return; V and F are ephemeral in this stub.

// Generate random but bounded, valid V (vertices) and F (simplices) matrices
// that satisfy igl::barycenter's requirements and exercise common paths.
// - V: (#V x dim) numeric coordinates
// - F: (#F x simplex_size) integral indices into rows of V (all in [0, #V-1])
// - BC: resized to (#F x dim)

// Use a single entropy source to avoid FUZZ_PARAM-in-loop limitation
std::string entropy = FUZZ_PARAM_STR();
if (entropy.empty()) { FUZZ_BAIL(); }
size_t eidx = 0;
auto next_u8 = [&](){ unsigned char b = entropy[eidx % entropy.size()]; eidx++; return (uint32_t)b; };
auto next_u32 = [&](){ uint32_t v = 0; v |= next_u8(); v |= (next_u8() << 8); v |= (next_u8() << 16); v |= (next_u8() << 24); return v; };

// Choose dimension and simplex size with typical mesh cases in mind
// dim in [1,4]; simplex_size in {2,3,4} biased by dim to stay realistic
int dim = (int)((next_u32() % 4u) + 1u);
int simplex_size;
switch(dim){
  case 1: simplex_size = 2; break;        // segments in 1D
  case 2: simplex_size = (next_u32()%2)?3:2; break; // edges or triangles in 2D
  case 3: simplex_size = (next_u32()%2)?4:3; break; // triangles or tets in 3D
  default: simplex_size = (int)((next_u32()%3u)+2u); break; // 2..4
}

// Bound sizes for performance; ensure #V >= simplex_size so F is indexable
int maxV = 128; int maxF = 128;
int nV = (int)(next_u32() % (uint32_t)maxV);
if (nV < simplex_size) nV = simplex_size; // enforce valid indexing domain
int nF = (int)(next_u32() % (uint32_t)maxF);

// Construct V with finite numeric values in a reasonable range [-1000,1000]
Eigen::Matrix<double, Eigen::Dynamic, Eigen::Dynamic> V(nV, dim);
for (int r = 0; r < nV; ++r) {
  for (int c = 0; c < dim; ++c) {
    double u = (double)(next_u32()) / 4294967295.0; // [0,1]
    V(r,c) = u * 2000.0 - 1000.0;                   // [-1000,1000]
  }
}

// Construct F with valid indices into [0, nV-1] and consistent simplex arity
Eigen::Matrix<int, Eigen::Dynamic, Eigen::Dynamic> F(nF, simplex_size);
for (int r = 0; r < nF; ++r) {
  for (int c = 0; c < simplex_size; ++c) {
    // Ensure index is valid; allow duplicates and any ordering (valid simplex specification)
    int idx = (int)(next_u32() % (uint32_t)nV);
    F(r,c) = idx;
  }
}

// Call target and collect result
Eigen::Matrix<double, Eigen::Dynamic, Eigen::Dynamic> BC;
igl::barycenter(V, F, BC);

// Validate required post-conditions: shapes must match (#F x dim)
FUZZ_ASSERT(BC.rows() == F.rows(), "BC row count must equal #F");
FUZZ_ASSERT(BC.cols() == V.cols(), "BC column count must equal dim");

// Nothing to return to the pool; matrices are ephemeral for this call only

// Generate a small random triangle mesh and call igl::per_vertex_normals
// Inputs: weighting (enum pointer) provided by the runtime; we dereference and validate it.
// Outputs: none (N is ephemeral here); assertions check expected properties.
{
    // 1) Validate and extract weighting enum
    if (!weighting) { FUZZ_BAIL(); }
    igl::PerVertexNormalsWeightingType w = *weighting;
    if (!(w == igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_UNIFORM ||
          w == igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_AREA ||
          w == igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_ANGLE ||
          w == igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_DEFAULT)) {
        // Enforce API requirement: weighting must be a valid enum value
        FUZZ_BAIL();
    }

    // 2) Choose mesh sizes within small bounds for performance
    unsigned int u_nv = *FUZZ_PARAM(unsigned int);
    unsigned int u_nf = *FUZZ_PARAM(unsigned int);
    int nv = (int)(u_nv % 32u) + 3;   // [3, 34] at least a minimal valid vertex count
    int nf = (int)(u_nf % 64u) + 1;   // [1, 64]

    // 3) Build reproducible random source from a fuzz string without reusing FUZZ_PARAM in loops
    std::string buf = FUZZ_PARAM_STR();
    size_t idx = 0;
    auto next_u32 = [&](){
        // Assemble a 32-bit value from 4 bytes; wrap around if we hit the end
        uint32_t v = 0;
        for (int i = 0; i < 4; ++i) {
            if (idx >= buf.size()) idx = 0;
            v = (v << 8) | (unsigned char)buf[idx++];
        }
        return v;
    };
    auto next_double = [&](){
        // Map u32 to [-1,1) as double
        uint32_t u = next_u32();
        double x = (double)(int32_t)u / (double)INT32_MAX; // roughly [-1,1]
        return x;
    };

    // 4) Materialize Eigen matrices: V (#V x 3), F (#F x 3), N (#V x 3)
    Eigen::Matrix<double, Eigen::Dynamic, 3> V(nv, 3);
    Eigen::Matrix<int,    Eigen::Dynamic, 3> F(nf, 3);
    for (int i = 0; i < nv; ++i) {
        V(i,0) = next_double();
        V(i,1) = next_double();
        V(i,2) = next_double();
    }
    for (int i = 0; i < nf; ++i) {
        // Enforce F indices in [0, nv-1]
        F(i,0) = (int)(next_u32() % (uint32_t)nv);
        F(i,1) = (int)(next_u32() % (uint32_t)nv);
        F(i,2) = (int)(next_u32() % (uint32_t)nv);
    }

    Eigen::Matrix<double, Eigen::Dynamic, 3> N; // output will be reshaped to (#V x 3)

    // 5) Invoke target function
    igl::per_vertex_normals(V, F, w, N);

    // 6) Validate core properties: N is (#V x 3)
    FUZZ_ASSERT(N.rows() == V.rows(), "per_vertex_normals: N.rows must equal V.rows");
    FUZZ_ASSERT(N.cols() == 3, "per_vertex_normals: N must have 3 columns");

    // No persistent objects to output; Eigen matrices are ephemeral within this stub.
    // Validation: We ensured a valid enum, bounded sizes, and in-range indices, then asserted N's shape.
}

// Obtain a readable filename from the fuzzer; contents are random and may not be valid OBJ.
// Per API, readOBJ returns false on parse failure; we intentionally allow both outcomes.
std::string obj_path = FUZZ_PARAM_FILENAME();

// Instantiate readOBJ with Scalar=double, Index=int via type deduction from containers.
{
    std::vector<std::vector<double>> V;
    std::vector<std::vector<double>> TC;
    std::vector<std::vector<double>> N;
    std::vector<std::vector<int>> F;
    std::vector<std::vector<int>> FTC;
    std::vector<std::vector<int>> FN;
    std::vector<std::tuple<std::string, int, int>> FM;

    bool ok = igl::readOBJ(obj_path, V, TC, N, F, FTC, FN, FM);
    (void)ok; // Checked by not asserting; false is a valid parse outcome.
}

// Instantiate readOBJ with Scalar=float, Index=unsigned int to exercise template coverage.
{
    std::vector<std::vector<float>> V;
    std::vector<std::vector<float>> TC;
    std::vector<std::vector<float>> N;
    std::vector<std::vector<unsigned int>> F;
    std::vector<std::vector<unsigned int>> FTC;
    std::vector<std::vector<unsigned int>> FN;
    std::vector<std::tuple<std::string, unsigned int, unsigned int>> FM;

    bool ok = igl::readOBJ(obj_path, V, TC, N, F, FTC, FN, FM);
    (void)ok;
}

// Validation: No inputs/outputs are persistent; all parameters are local lvalues as required.
// We avoid filesystem operations to ensure toolchain compatibility and rely on the fuzzer-provided readable file.

// Generate a writable output path
std::string path = FUZZ_PARAM_FILENAME();

// Choose mesh sizes within modest bounds to keep allocations small
unsigned int seed = *FUZZ_PARAM(unsigned int);
int nV = (int)(seed % 64) + 1; // at least 1 vertex
seed = seed * 1103515245u + 12345u;
int nF = (int)((seed >> 8) % 64); // possibly 0 faces
seed = seed * 1103515245u + 12345u;
bool quads = ((seed >> 16) & 1u) != 0; // 3 or 4 indices per face
int f_cols = quads ? 4 : 3;

// Optional channels
seed = seed * 1103515245u + 12345u;
bool enable_normals = ((seed >> 24) & 1u) != 0;
seed = seed * 1103515245u + 12345u;
bool enable_tex = ((seed >> 20) & 1u) != 0;

// Construct vertex positions V (#V x 3)
Eigen::MatrixXd V(nV, 3);
// Use deterministic pseudo-random values derived from seeds and indices; avoid FUZZ_PARAM in loops
double a = (double)((*FUZZ_PARAM(int)) | 1); // odd to avoid zeros in linear recurrences
double b = (double)((*FUZZ_PARAM(int)) ^ 0x5a5a5a5a);
for (int i = 0; i < nV; ++i) {
  for (int j = 0; j < 3; ++j) {
    double v = (a * (i + 1) + b * (j + 1));
    // keep values bounded
    V(i, j) = std::sin(v) * 10.0;
  }
}

// Construct faces F (#F x 3 or 4), indices in [0, nV-1]
Eigen::MatrixXi F;
if (nF > 0) {
  F.resize(nF, f_cols);
  // base stride to distribute indices within range
  int step = (int)((*FUZZ_PARAM(unsigned int)) % std::max(1, nV));
  if (step == 0) step = 1;
  for (int i = 0; i < nF; ++i) {
    for (int j = 0; j < f_cols; ++j) {
      F(i, j) = (i * step + j) % nV; // guaranteed in-range
    }
  }
}

// Normals (CN, FN)
Eigen::MatrixXd CN;      // #CN x 3
Eigen::MatrixXi FN;      // #F  x 3/4
if (enable_normals) {
  int nCN = (int)((*FUZZ_PARAM(unsigned int)) % 64);
  if (nF > 0 && nCN == 0) nCN = 1; // if faces exist, ensure at least one normal so FN can reference something
  CN.resize(nCN, 3);
  double na = (double)((*FUZZ_PARAM(int)) | 1);
  double nb = (double)((*FUZZ_PARAM(int)) ^ 0x33cc33cc);
  for (int i = 0; i < nCN; ++i) {
    for (int j = 0; j < 3; ++j) {
      double v = (na * (i + 2) + nb * (j + 3));
      CN(i, j) = std::cos(v);
    }
  }
  if (nF > 0) {
    FN.resize(nF, f_cols);
    int ncn = std::max(1, (int)CN.rows());
    int stepN = (int)((*FUZZ_PARAM(unsigned int)) % ncn);
    if (stepN == 0) stepN = 1;
    for (int i = 0; i < nF; ++i) {
      for (int j = 0; j < f_cols; ++j) {
        FN(i, j) = (i * stepN + j) % ncn; // in-range for CN
      }
    }
  }
}

// Texture coordinates (TC, FTC)
Eigen::MatrixXd TC;      // #TC x 2 or 3
Eigen::MatrixXi FTC;     // #F  x 3/4
if (enable_tex) {
  bool tc3 = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0; // 2D or 3D texcoords
  int tc_cols = tc3 ? 3 : 2;
  int nTC = (int)((*FUZZ_PARAM(unsigned int)) % 64);
  if (nF > 0 && nTC == 0) nTC = 1; // ensure indexability if faces exist
  TC.resize(nTC, tc_cols);
  double ta = (double)((*FUZZ_PARAM(int)) | 1);
  double tb = (double)((*FUZZ_PARAM(int)) ^ 0x0f0f0f0f);
  for (int i = 0; i < nTC; ++i) {
    for (int j = 0; j < tc_cols; ++j) {
      double v = (ta * (i + 5) + tb * (j + 7));
      TC(i, j) = std::sin(v * 0.5);
    }
  }
  if (nF > 0) {
    FTC.resize(nF, f_cols);
    int ntc = std::max(1, (int)TC.rows());
    int stepT = (int)((*FUZZ_PARAM(unsigned int)) % ntc);
    if (stepT == 0) stepT = 1;
    for (int i = 0; i < nF; ++i) {
      for (int j = 0; j < f_cols; ++j) {
        FTC(i, j) = (i * stepT + j) % ntc; // in-range for TC
      }
    }
  }
}

// Enforce basic invariants before calling:
// - V is #V x 3
// - If F present, columns are 3 or 4 and indices < V.rows()
// - If CN/FN present, CN is #CN x 3 and FN matches F's shape with indices < CN.rows()
// - If TC/FTC present, TC is #TC x {2,3} and FTC matches F's shape with indices < TC.rows()
if (F.size() > 0) {
  for (int i = 0; i < F.rows(); ++i) {
    for (int j = 0; j < F.cols(); ++j) {
      if (F(i, j) < 0 || F(i, j) >= V.rows()) { FUZZ_BAIL(); }
    }
  }
}
if (FN.size() > 0) {
  if (FN.rows() != F.rows() || FN.cols() != F.cols()) { FUZZ_BAIL(); }
  for (int i = 0; i < FN.rows(); ++i) {
    for (int j = 0; j < FN.cols(); ++j) {
      if (FN(i, j) < 0 || FN(i, j) >= CN.rows()) { FUZZ_BAIL(); }
    }
  }
}
if (FTC.size() > 0) {
  if (FTC.rows() != F.rows() || FTC.cols() != F.cols()) { FUZZ_BAIL(); }
  for (int i = 0; i < FTC.rows(); ++i) {
    for (int j = 0; j < FTC.cols(); ++j) {
      if (FTC(i, j) < 0 || FTC(i, j) >= TC.rows()) { FUZZ_BAIL(); }
    }
  }
}

// Invoke the target function. False is a valid error return; bail to let fuzzer explore causes.
bool ok = igl::writeOBJ(path, V, F, CN, FN, TC, FTC);
if (!ok) { FUZZ_BAIL(); }

// Construct a valid igl::PerVertexNormalsWeightingType value and return it as a managed pointer.
// This enum is user-managed: allocate on the heap, initialize to a valid value in [0..3].

// 1) Choose a valid enum value from fuzzer entropy
unsigned int r = *FUZZ_PARAM(unsigned int);
unsigned int choice = r % (unsigned int)igl::NUM_PER_VERTEX_NORMALS_WEIGHTING_TYPE; // 0..3 valid; 4 is NUM_*
igl::PerVertexNormalsWeightingType selected;
switch(choice){
  case (unsigned int)igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_UNIFORM:
    selected = igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_UNIFORM; break;
  case (unsigned int)igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_AREA:
    selected = igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_AREA; break;
  case (unsigned int)igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_ANGLE:
    selected = igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_ANGLE; break;
  default:
    // Map any remaining value (e.g., 3) to DEFAULT as per API
    selected = igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_DEFAULT; break;
}

// 2) Allocate output pointer and initialize; ensure non-null per fuzzer contract
igl::PerVertexNormalsWeightingType *weighting = new (std::nothrow) igl::PerVertexNormalsWeightingType;
if (!weighting) { FUZZ_BAIL(); }
*weighting = selected;

// 3) Track attributes for downstream validation/usage
FUZZ_SET_ATTR_INT(weighting, "enum.valid", 1);
FUZZ_SET_ATTR_INT(weighting, "enum.value", (int)(*weighting));

// 4) Validate produced value is one of the documented options
FUZZ_ASSERT(
  (*weighting == igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_UNIFORM ||
   *weighting == igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_AREA ||
   *weighting == igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_ANGLE ||
   *weighting == igl::PER_VERTEX_NORMALS_WEIGHTING_TYPE_DEFAULT),
  "Constructed weighting must be a valid PerVertexNormalsWeightingType");

// Validation summary: We declare and initialize the output pointer, guarantee non-null, constrain the
// enum to valid values, and attach attributes for safe downstream use.

