import random
from typing import List

def _rand_sign(rng: random.Random) -> int:
    return -1 if rng.random() < 0.5 else 1

def _rand_float(rng: random.Random, a=-10.0, b=10.0) -> float:
    return rng.uniform(a, b)

def _choose(rng: random.Random, seq):
    return seq[rng.randrange(len(seq))]

def _format_float(x: float) -> str:
    # Keep reasonable precision while avoiding scientific notation for OBJ readability
    return ("%.6f" % x).rstrip('0').rstrip('.') if '.' in ("%.6f" % x) else str(int(x))

def _make_header(rng: random.Random) -> List[str]:
    lines = []
    # Optional comments and mtllib references
    for _ in range(rng.randint(0, 3)):
        lines.append(f"# comment {_}")
    if rng.random() < 0.6:
        # include one or more mtllib statements
        nlib = rng.randint(1, 2)
        for i in range(nlib):
            name = _choose(rng, ["mat.mtl", "materials.mtl", "tex.mtl", "m.mtl"]) if rng.random() < 0.7 else f"m{rng.randint(0,999)}.mtl"
            lines.append(f"mtllib {name}")
    # Optional object/group
    if rng.random() < 0.7:
        lines.append(f"o obj_{rng.randint(0,999)}")
    if rng.random() < 0.7:
        lines.append(f"g group_{rng.randint(0,999)}")
    return lines

def _gen_vertices(rng: random.Random, nV: int, dim: int) -> List[str]:
    lines = []
    for _ in range(nV):
        if dim == 2:
            x, y = _rand_float(rng), _rand_float(rng)
            z = 0.0 if rng.random() < 0.7 else _rand_float(rng)
        else:
            x, y, z = _rand_float(rng), _rand_float(rng), _rand_float(rng)
        if rng.random() < 0.2:
            # homogeneous w coordinate
            w = rng.choice([1.0, rng.uniform(0.1, 5.0)])
            lines.append(f"v {_format_float(x)} {_format_float(y)} {_format_float(z)} {_format_float(w)}")
        else:
            lines.append(f"v {_format_float(x)} {_format_float(y)} {_format_float(z)}")
    return lines

def _gen_texcoords(rng: random.Random, nVT: int) -> List[str]:
    lines = []
    for _ in range(nVT):
        u = rng.random()
        v = rng.random()
        if rng.random() < 0.5:
            w = rng.random()
            lines.append(f"vt {_format_float(u)} {_format_float(v)} {_format_float(w)}")
        else:
            lines.append(f"vt {_format_float(u)} {_format_float(v)}")
    return lines

def _gen_normals(rng: random.Random, nVN: int) -> List[str]:
    lines = []
    for _ in range(nVN):
        # Random unit-ish vector (not strictly normalized to allow library to handle)
        x, y, z = _rand_float(rng, -1, 1), _rand_float(rng, -1, 1), _rand_float(rng, -1, 1)
        lines.append(f"vn {_format_float(x)} {_format_float(y)} {_format_float(z)}")
    return lines

def _face_indices(rng: random.Random, nv: int, nV: int, nVT: int, nVN: int, use_negative: bool) -> List[str]:
    # Choose distinct vertex indices (1-based), allow polygons (nv>=3). Ensure valid references.
    # For variety, sometimes use negative indexing relative to end (OBJ supports -k indexing).
    verts = []
    chosen = set()
    for _ in range(nv):
        while True:
            idx = rng.randint(1, nV)
            if idx not in chosen or rng.random() < 0.2:
                chosen.add(idx)
                break
        def maybe_neg(i, total):
            if use_negative and rng.random() < 0.5:
                # negative index -k refers to current list end; simulate typical valid range
                # Clamp k within [1,total]
                k = rng.randint(1, total)
                return f"-{k}"
            return str(i)
        v_str = maybe_neg(idx, nV)
        has_vt = nVT > 0 and rng.random() < 0.8
        has_vn = nVN > 0 and rng.random() < 0.8
        if has_vt and has_vn:
            t = maybe_neg(rng.randint(1, nVT), nVT)
            n = maybe_neg(rng.randint(1, nVN), nVN)
            verts.append(f"{v_str}/{t}/{n}")
        elif has_vt and not has_vn:
            t = maybe_neg(rng.randint(1, nVT), nVT)
            verts.append(f"{v_str}/{t}")
        elif (not has_vt) and has_vn:
            n = maybe_neg(rng.randint(1, nVN), nVN)
            verts.append(f"{v_str}//{n}")
        else:
            verts.append(v_str)
    return verts

def _gen_faces(rng: random.Random, nF: int, nV: int, nVT: int, nVN: int) -> List[str]:
    lines = []
    for fi in range(nF):
        # mix of triangles and quads/polygons
        nv = _choose(rng, [3, 3, 4, 5]) if nV >= 5 else (3 if nV >= 3 else nV)
        use_neg = rng.random() < 0.3
        verts = _face_indices(rng, nv, nV, nVT, nVN, use_neg)
        if rng.random() < 0.3:
            # start a new usemtl occasionally
            lines.append(f"usemtl m_{fi%3}")
        lines.append("f " + " ".join(verts))
    return lines

def _gen_subelements(rng: random.Random, nV: int) -> List[str]:
    lines = []
    # Optional parameter space curves/points (rare in practice but valid)
    if rng.random() < 0.2:
        lines.append(f"vp {_format_float(rng.random())}")
    # Lines (l) referencing vertices or vt
    if rng.random() < 0.3 and nV >= 2:
        a = rng.randint(1, nV)
        b = rng.randint(1, nV)
        lines.append(f"l {a} {b}")
    return lines

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide counts, keeping file under 4096 bytes while still interesting
    nV = rng.randint(8, 60)
    nVT = rng.randint(0, max(0, nV // 2))
    nVN = rng.randint(0, max(0, nV // 2))
    nF = rng.randint(max(1, nV // 4), max(2, nV // 2))

    lines: List[str] = []
    lines.extend(_make_header(rng))

    # Scale block to keep coordinates in a typical range
    if rng.random() < 0.5:
        s = rng.uniform(0.1, 5.0) * _rand_sign(rng)
        lines.append(f"s {_format_float(abs(s))}")

    # Vertices, texture coords, normals
    lines.extend(_gen_vertices(rng, nV, 3))
    if nVT > 0:
        lines.extend(_gen_texcoords(rng, nVT))
    if nVN > 0:
        lines.extend(_gen_normals(rng, nVN))

    # Subelements like groups and smoothing groups variations
    if rng.random() < 0.5:
        lines.append(f"g g0 g1")
    if rng.random() < 0.7:
        lines.append(_choose(rng, ["s off", "s 1", "s 2"]))

    # Faces
    lines.extend(_gen_faces(rng, nF, nV, nVT, nVN))

    # Optional more groups/material switches interleaved
    lines.extend(_gen_subelements(rng, nV))

    # Ensure newline at end
    text = "\n".join(lines) + "\n"

    # Truncate defensively to stay within 4096 bytes
    by = text.encode('utf-8')
    if len(by) > 4096:
        by = by[:4096]
        # Ensure we end with a newline to not cut a token mid-line in some cases
        if not by.endswith(b"\n"):
            by = by.rsplit(b"\n", 1)[0] + b"\n"
    return by
